import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    k = int(data[0])
    a = []
    idx = 1
    for _ in range(k):
        a.append(int(data[idx]))
        idx += 1

    a.sort(reverse=True)

    total_beauty = 0
    current_level_count = 1
    index = 0

    while current_level_count <= k:
        for _ in range(current_level_count):
            if index < len(a):
                total_beauty += a[index]
                index += 1

        if current_level_count * 4 > k:
            break
        current_level_count *= 4

    print(total_beauty)

if __name__ == "__main__":
    main()
